<script setup lang="ts">
import{ref}from 'vue';import{useRouter}from 'vue-router';import{api}from '@/api/client';import{useAuthStore}from '@/stores/auth';const router=useRouter();const auth=useAuthStore();const tenant=ref('');const name=ref('');const email=ref('');const password=ref('');const confirmation=ref('');const error=ref('');const busy=ref(false);async function submit(){error.value='';if(!tenant.value||!name.value||password.value.length<12||password.value!==confirmation.value){error.value='Enter your facility, name, matching passwords, and use at least 12 password characters.';return}busy.value=true;try{const r=await api.post('/auth/register',{tenant_name:tenant.value,name:name.value,email:email.value,password:password.value,password_confirmation:confirmation.value,device_name:'Court Hub Web'});const p=r.data.data??r.data;auth.setSession(p.token,p.user);router.push('/')}catch(e:any){error.value=e.response?.data?.message??'Account could not be created.'}finally{busy.value=false}}</script>
<template><main class="login-page"><section class="login-panel"><RouterLink class="brand" to="/login"><span class="brand-mark">C</span> Court Hub</RouterLink><p class="eyebrow">CREATE FACILITY ACCOUNT</p><h1>Start your Court Hub.</h1><p class="muted">This creates a new facility owner account and tenant.</p><form @submit.prevent="submit"><label>Facility or tenant name<input v-model="tenant"/></label><label>Your name<input v-model="name"/></label><label>Email<input v-model="email" type="email"/></label><label>Password<input v-model="password" type="password"/></label><label>Confirm password<input v-model="confirmation" type="password"/></label><p v-if="error" class="form-error">{{error}}</p><button class="primary-button" :disabled="busy">{{busy?'Creating…':'Create facility account'}}</button></form><p class="login-note">Already have an account? <RouterLink to="/login">Sign in</RouterLink></p></section><section class="login-art"><div><p class="eyebrow">COURT HUB</p><h2>Build a better facility experience.</h2></div></section></main></template>
